system/fvSchemes.text:
FoamFile
{
 version 2.0;
 format ascii;
 class dictionary;
 object fvSchemes;
}
ddtSchemes
{
 default steadyState;
}
gradSchemes
{
 default Gauss linear;
 grad(U) cellLimited Gauss linear 1;
}
divSchemes
{
 default none;
 div(phi,U) bounded Gauss linearUpwind grad(U);
 div(phi,k) bounded Gauss limitedLinear 1;
 div(phi,epsilon) bounded Gauss limitedLinear 1;
 div(phi,omega) bounded Gauss limitedLinear 1;
 div(phi,v2) bounded Gauss limitedLinear 1;
 div((nuEff*dev2(T(grad(U))))) Gauss linear;
 div(nonlinearStress) Gauss linear;
}
laplacianSchemes
{
 default Gauss linear corrected;
}
interpolationSchemes
{
 default linear;
}
snGradSchemes
{
 default corrected;
}
wallDist
{
 method meshWave;
}

system/fvSolution.text:
FoamFile
{
 version 2.0;
 format ascii;
 class dictionary;
 object fvSolution;
}
solvers
{
 p { solver GAMG; tolerance 1e-12; relTol 0.01; smoother GaussSeidel; }
 U { solver smoothSolver; smoother symGaussSeidel; tolerance 1e-12; relTol 0.01; }
}
SIMPLE
{
 nNonOrthogonalCorrectors 2;
 consistent yes;
 residualControl { p 1e-6; U 1e-6; }
}
relaxationFactors
{
 equations { U 0.7; }
 fields    { p 0.3; }
}

