FoamFile
{
 version 2.0;
 format ascii;
 class volScalarField;
 object p;
}
dimensions [0 2 -2 0 0 0 0];
internalField uniform 0;
boundaryField
{
 nostril_L {
type fixedValue; value uniform 8.333333333333334;
}
 nostril_R {
type fixedValue; value uniform 8.333333333333334;
}
 nasopharynx_outlet {
type fixedValue; value uniform 0;
}
 wall { type zeroGradient; }
}

